svg.script:
//
(function () {
  var root = document.getElementById('figContinuity');
  if (!root || root.getAttribute('data-ready') === '1') { return; }
  root.setAttribute('data-ready', '1');

  var HP_MIN = 25, HP_MAX = 45;
  var PLOT = { x0: 110, x1: 700, y0: 90, y1: 380 };   // y0 = value 1, y1 = value 0

  // Documented anchors (from the post): HP 29 / 31 / 35.
  // The surrounding points are plausible shaping so the curve covers the axis;
  // interpolation is monotone cubic, so no overshoot between anchors.
  var POINTS = [
    { hp: 25, retreat: 1.00, attack: 0.00, resupply: 0.00 },
    { hp: 29, retreat: 0.90, attack: 0.10, resupply: 0.00 },
    { hp: 31, retreat: 0.70, attack: 0.20, resupply: 0.10 },
    { hp: 33, retreat: 0.50, attack: 0.40, resupply: 0.10 },
    { hp: 35, retreat: 0.30, attack: 0.60, resupply: 0.10 },
    { hp: 38, retreat: 0.12, attack: 0.80, resupply: 0.08 },
    { hp: 41, retreat: 0.05, attack: 0.90, resupply: 0.05 },
    { hp: 45, retreat: 0.02, attack: 0.95, resupply: 0.03 }
  ];
  var KEYS = ['retreat', 'attack', 'resupply'];
  var ACTIVE = { retreat: 'figContBarRetreat', attack: 'figContBarAttack', resupply: 'figContBarResupply' };
  var VALUES = { retreat: 'figContValRetreat', attack: 'figContValAttack', resupply: 'figContValResupply' };

  function monotoneSlopes(xs, ys) {
    var n = xs.length, h = [], d = [], m = [], i;
    for (i = 0; i < n - 1; i++) {
      h[i] = xs[i + 1] - xs[i];
      d[i] = (ys[i + 1] - ys[i]) / h[i];
    }
    m[0] = d[0]; m[n - 1] = d[n - 2];
    for (i = 1; i < n - 1; i++) {
      m[i] = (d[i - 1] * d[i] <= 0) ? 0 : (d[i - 1] + d[i]) / 2;
    }
    for (i = 0; i < n - 1; i++) {
      if (d[i] === 0) { m[i] = 0; m[i + 1] = 0; continue; }
      var a = m[i] / d[i], b = m[i + 1] / d[i], s = a * a + b * b;
      if (s > 9) {
        var t = 3 / Math.sqrt(s);
        m[i] = t * a * d[i];
        m[i + 1] = t * b * d[i];
      }
    }
    return { h: h, m: m };
  }

  function evaluate(key) {
    var xs = POINTS.map(function (p) { return p.hp; });
    var ys = POINTS.map(function (p) { return p[key]; });
    var st = monotoneSlopes(xs, ys), n = xs.length;
    return function (hp) {
      if (hp <= xs[0]) { return ys[0]; }
      if (hp >= xs[n - 1]) { return ys[n - 1]; }
      var i = 0;
      while (i < n - 2 && hp > xs[i + 1]) { i++; }
      var t = (hp - xs[i]) / st.h[i], t2 = t * t, t3 = t2 * t;
      var h00 = 2 * t3 - 3 * t2 + 1, h10 = t3 - 2 * t2 + t;
      var h01 = -2 * t3 + 3 * t2, h11 = t3 - t2;
      return h00 * ys[i] + h10 * st.h[i] * st.m[i] + h01 * ys[i + 1] + h11 * st.h[i] * st.m[i + 1];
    };
  }

  var evalFn = {};
  KEYS.forEach(function (k) { evalFn[k] = evaluate(k); });

  function toX(hp) { return PLOT.x0 + (hp - HP_MIN) / (HP_MAX - HP_MIN) * (PLOT.x1 - PLOT.x0); }
  function toY(v) { return PLOT.y1 - v * (PLOT.y1 - PLOT.y0); }

  function stepValue(key, hp) {
    // The if/else version: a single threshold at 30% HP.
    if (key === 'retreat') { return hp < 30 ? 1 : 0; }
    if (key === 'attack') { return hp < 30 ? 0 : 1; }
    return 0.05;
  }

  function buildPath(mode, key) {
    var d = '', first = true, i, hp, v;
    if (mode === 'step') {
      // draw true steps: two samples per segment with a vertical jump at 30%
      var xs = [];
      for (i = 0; i <= 400; i++) { xs.push(HP_MIN + (HP_MAX - HP_MIN) * i / 400); }
      for (i = 0; i < xs.length; i++) {
        hp = xs[i]; v = stepValue(key, hp);
        if (first) { d += 'M' + toX(hp).toFixed(2) + ' ' + toY(v).toFixed(2); first = false; }
        else {
          var prev = stepValue(key, xs[i - 1]);
          if (v !== prev) { d += ' L' + toX(hp).toFixed(2) + ' ' + toY(prev).toFixed(2); }
          d += ' L' + toX(hp).toFixed(2) + ' ' + toY(v).toFixed(2);
        }
      }
      return d;
    }
    for (i = 0; i <= 400; i++) {
      hp = HP_MIN + (HP_MAX - HP_MIN) * i / 400;
      v = Math.max(0, Math.min(1, evalFn[key](hp)));
      d += (first ? 'M' : ' L') + toX(hp).toFixed(2) + ' ' + toY(v).toFixed(2);
      first = false;
    }
    return d;
  }

  var NS = 'http://www.w3.org/2000/svg';
  var curvesG = document.getElementById('figContCurves');
  var anchorsG = document.getElementById('figContAnchors');
  var paths = { step: {}, cont: {} };

  KEYS.forEach(function (k) {
    ['step', 'cont'].forEach(function (mode) {
      var p = document.createElementNS(NS, 'path');
      p.setAttribute('class', 'curve-' + k);
      p.setAttribute('d', buildPath(mode, k));
      p.setAttribute('data-mode', mode);
      curvesG.appendChild(p);
      paths[mode][k] = p;
    });
  });

  var ANCHOR_HP = [29, 31, 35];
  ANCHOR_HP.forEach(function (hp) {
    KEYS.forEach(function (k) {
      var c = document.createElementNS(NS, 'circle');
      c.setAttribute('class', 'anchor-dot');
      c.setAttribute('cx', toX(hp).toFixed(2));
      c.setAttribute('cy', toY(evalFn[k](hp)).toFixed(2));
      c.setAttribute('r', 4);
      c.setAttribute('fill', k === 'retreat' ? '#0083b0' : (k === 'attack' ? '#e67e22' : '#27ae60'));
      anchorsG.appendChild(c);
    });
    var t = document.createElementNS(NS, 'text');
    t.setAttribute('class', 'anchor-label muted');
    t.setAttribute('x', toX(hp).toFixed(2));
    t.setAttribute('y', (PLOT.y1 + 18).toFixed(2));
    t.setAttribute('text-anchor', 'middle');
    t.textContent = hp + '%';
    anchorsG.appendChild(t);
  });

  var guide = document.getElementById('figContGuide');
  var hpOut = document.getElementById('figContHp');
  var modeOut = document.getElementById('figContMode');
  var verdict = document.getElementById('figContVerdict');
  var state = { hp: 31, mode: 'cont' };

  function valueAt(key, hp) {
    return state.mode === 'step' ? stepValue(key, hp) : Math.max(0, Math.min(1, evalFn[key](hp)));
  }

  function render() {
    var hp = state.hp, step = state.mode === 'step';
    KEYS.forEach(function (k) {
      paths.step[k].style.display = step ? '' : 'none';
      paths.cont[k].style.display = step ? 'none' : '';
    });
    anchorsG.style.display = step ? 'none' : '';
    guide.style.display = '';
    guide.setAttribute('x1', toX(hp).toFixed(2));
    guide.setAttribute('x2', toX(hp).toFixed(2));
    hpOut.textContent = hp.toFixed(1) + '%';
    modeOut.textContent = step ? 'if / else — one threshold at 30%' : 'XML + network Δ';
    KEYS.forEach(function (k) {
      var v = valueAt(k, hp);
      document.getElementById(ACTIVE[k]).setAttribute('width', (v * 160).toFixed(2));
      document.getElementById(VALUES[k]).textContent = v.toFixed(2);
    });
    if (step) {
      verdict.textContent = hp < 30 ? 'Retreat 100% — snapped' : 'Attack 100% — snapped';
    } else {
      verdict.textContent = 'Blended: ' + [valueAt('retreat', hp), valueAt('attack', hp), valueAt('resupply', hp)]
        .map(function (v) { return v.toFixed(2); }).join(' / ');
    }
    root.setAttribute('aria-label',
      'Own HP ' + hp.toFixed(1) + '%. Retreat ' + valueAt('retreat', hp).toFixed(2) +
      ', attack ' + valueAt('attack', hp).toFixed(2) + ', resupply ' + valueAt('resupply', hp).toFixed(2) + '.');
  }

  function setMode(mode) {
    state.mode = mode;
    var step = mode === 'step';
    document.querySelector('.fig-continuity .mode-step .btn').classList.toggle('btn-active', step);
    document.querySelector('.fig-continuity .mode-cont .btn').classList.toggle('btn-active', !step);
    document.querySelector('.fig-continuity .btn-step-text').classList.toggle('btn-text-active', step);
    document.querySelector('.fig-continuity .btn-cont-text').classList.toggle('btn-text-active', !step);
    render();
  }

  // Only the plot rectangle reacts to the pointer: clicking the mode buttons,
  // the legend or the readout panel must not silently move the cursor.
  function hpFromEvent(evt) {
    var box = root.getBoundingClientRect();
    var scale = 980 / box.width;
    var x = (evt.clientX - box.left) * scale;
    var y = (evt.clientY - box.top) * scale;
    if (x < PLOT.x0 || x > PLOT.x1 || y < PLOT.y0 || y > PLOT.y1) { return null; }
    var hp = HP_MIN + (x - PLOT.x0) / (PLOT.x1 - PLOT.x0) * (HP_MAX - HP_MIN);
    return Math.max(HP_MIN, Math.min(HP_MAX, hp));
  }

  function handlePointer(e) {
    var hp = hpFromEvent(e);
    if (hp === null) { return; }
    state.hp = hp;
    render();
  }

  root.addEventListener('pointermove', handlePointer);
  root.addEventListener('pointerdown', handlePointer);
  document.querySelector('.fig-continuity .mode-step').addEventListener('click', function () { setMode('step'); });
  document.querySelector('.fig-continuity .mode-cont').addEventListener('click', function () { setMode('cont'); });
  document.querySelector('.fig-continuity .mode-step').addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setMode('step'); }
  });
  document.querySelector('.fig-continuity .mode-cont').addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setMode('cont'); }
  });
  root.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowRight') { state.hp = Math.min(HP_MAX, state.hp + 0.5); render(); e.preventDefault(); }
    if (e.key === 'ArrowLeft') { state.hp = Math.max(HP_MIN, state.hp - 0.5); render(); e.preventDefault(); }
  });

  setMode('cont');
})();
//
